// Read a dotnet build log, group compile errors by block .razor file, and emit
// a Workflow script that fixes each file (one agent per file, given its exact
// errors). Excludes *BlocksPage.razor (regenerated by gen-blockpages) and .g.cs.
//
// Usage: node scripts/gen-fix-workflow.mjs artifacts/shadcnio/build3.log
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const logPath = process.argv[2];
if (!logPath) { console.error('usage: gen-fix-workflow.mjs <build.log>'); process.exit(1); }
const log = fs.readFileSync(path.join(ROOT, logPath), 'utf8');

const byFile = {};
const re = /^(.*?\.razor)\((\d+),(\d+)\): error (\w+): (.*?)\s*(?:\[.*)?$/gm;
let m;
while ((m = re.exec(log))) {
  const [, file, line, col, code, msg] = m;
  if (file.endsWith('BlocksPage.razor')) continue; // codegen handles these
  const abs = file.replace(/\\/g, '/');
  (byFile[abs] ||= []).push(`(${line},${col}) ${code}: ${msg}`);
}
const files = Object.entries(byFile).map(([file, errors]) => ({ file, errors }));
if (!files.length) { console.log('no block-file errors to fix'); process.exit(0); }

const PLAYBOOK = String.raw`A previously-generated BlazorCN demo block (.razor) FAILS TO COMPILE. Fix it with the MINIMAL change that makes it valid, COMPILING Razor while preserving the same UI/behavior.

FILE: %%FILE%%
COMPILER ERRORS:
%%ERRORS%%

STEP 1 — Read the file.
STEP 2 — Fix ONLY what's needed for these errors (and any obviously-identical sibling mistakes in the same file). Common causes and fixes:
- "complex content (mixed C# and markup)" on an attribute, or "The name 'X' does not exist" where X is a word after a literal @ (emails, @mentions, @media): a literal "@" in text/attribute must be "@@" in plain HTML text, OR — inside a COMPONENT attribute value — wrap the whole value as a C# string: Attr="@("text with @ inside")". To inject a value use Attr="@($"prefix-{x.Id}")".
- 'Unexpected "{" after "@"': you wrote "@{" in markup wrongly. Remove it; compute per-item values INSIDE @foreach braces (var y = ...; no @), or move logic to @code.
- "The name 'Foo' does not exist": you referenced a method/field/enum not defined. Either define it in @code, or replace with inline logic. For GUESSED component enums that don't exist (e.g. TooltipSide, SeparatorOrientation, TooltipPlacement, ...Orientation), REMOVE that component usage and render the raw HTML equivalent with the same Tailwind classes (e.g. <hr class="..."/> or a plain styled div). Known-good enums only: ButtonVariant/ButtonSize/BadgeVariant.
- "RuntimeHelpers.TypeCheck" / TypeCheck errors usually cascade from a broken attribute above — fixing the attribute clears them.
- "'section' directive must appear at the start of the line" (RZ2005/RZ1011): a loop/local variable is named 'section' (or 'code'/'functions'/'inherits'/'page'/'model' — all reserved Razor directives), so "@section.X" is read as the @section directive. RENAME the variable (e.g. section->sec, code->cd) everywhere in the file.
- "CS9000: Raw string literal delimiter must be on its own line": replace any C# raw string literal (""" ... """) with a normal verbatim string @"..." (double internal quotes) or a regular "..." string; raw strings are fragile inside Razor @code.
- "CS8917: delegate type could not be inferred": an event handler lambda is ambiguous — give it a type, e.g. @onclick="@((MouseEventArgs e) => ...)" / @onchange="@((ChangeEventArgs e) => ...)" , or wrap a value-returning lambda body in braces { ... } so it's an Action.
- "CS1061: does not contain a definition for 'Length'": you called .Length on a List<T> — use .Count (List) ; .Length is for arrays/string. Conversely .Count() (LINQ) works on both.
- "CS0103: 'disabled' does not exist": you wrote a raw disabled="@disabled" referencing an undefined field — either define it, or on a *Cn component use Disabled="@(...)" with a real expression, or drop it.
- "CS0116: namespace cannot directly contain members" / a type not found that IS defined in @code: usually a C# string literal was broken. Common cause: Razor escapes leaked INTO the @code block — e.g. data text written as "...@("{") event @("}")..." or "a@@b". Inside @code (pure C#), there is NO Razor escaping: write literal { } @ and a normal "..." string. Replace @("{")->{ , @("}")->} , @@->@ , and make sure each string's quotes are balanced.
STEP 3 — Edit the file in place (Edit/Write). Keep all visible text and Tailwind classes identical. Return { file, fixed:true, change }.`;

const SCHEMA = { type: 'object', additionalProperties: false, properties: { file: { type: 'string' }, fixed: { type: 'boolean' }, change: { type: 'string' } }, required: ['file', 'fixed'] };

const batch = files.map((f) => ({ file: path.join(ROOT, f.file).replace(/\\/g, '/'), errors: f.errors.join('\n') }));
const out = `export const meta = {
  name: 'fix-blocks',
  description: 'Fix compile errors in ${batch.length} BlazorCN block files',
  phases: [{ title: 'Fix', detail: 'one agent per broken file' }],
}
const SCHEMA = ${JSON.stringify(SCHEMA)}
const PLAYBOOK = ${JSON.stringify(PLAYBOOK)}
const BATCH = ${JSON.stringify(batch)}
function prompt(b){ return PLAYBOOK.replaceAll('%%FILE%%', b.file).replaceAll('%%ERRORS%%', b.errors) }
phase('Fix')
log('Fixing ' + BATCH.length + ' files')
const results = await parallel(BATCH.map(b => () => agent(prompt(b), { schema: SCHEMA, phase: 'Fix', label: b.file.split('/').pop(), model: 'sonnet' })))
const ok = results.filter(Boolean)
return { requested: BATCH.length, fixed: ok.filter(r => r.fixed).length, changes: ok.map(r => ({ file: (r.file||'').split('/').pop(), change: r.change })) }
`;
fs.writeFileSync(path.join(ROOT, 'scripts', '_fix-wf.mjs'), out);
console.log(`wrote scripts/_fix-wf.mjs with ${batch.length} files:`);
for (const f of files) console.log('  ', f.file.split('/').pop(), '->', f.errors.length, 'errors');
